<?php
declare(strict_types=1);
session_start();
require __DIR__.'/config.php';
$pdo=store_db();
$cats=$pdo->query("SELECT id,name,image FROM categories WHERE is_active=1 ORDER BY sort_order,id")->fetchAll();
