?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>الفخامة للشيشة والتبغ</title><link href="https://fonts.googleapis.com/css2?family=Cairo:wght@400;600;700;900&display=swap" rel="stylesheet"><link rel="stylesheet" href="assets/css/store.css"></head><body><div class="top">♢ متجر موثوق وآمن　　🚚 التوصيل متوفر لجميع المناطق　　☎ 053 123 4567</div><header><a class="logo" href="#">♧ الفخامة <small>Al Fakhamah</small></a><nav><a href="#">الرئيسية</a><a href="#cats">الأقسام</a><a href="#products">المنتجات</a></nav><a class="cart" href="cart.php">🛒 السلة</a></header><section class="hero"><div class="hero-text"><small>مرحباً بكم في</small><h1>الفخامة للشيشة والتبغ</h1><p>اكتشف تجربة فاخرة لا مثيل لها</p><a class="gold" href="#products">تسوق الآن　🛒</a></div><button class="prev">‹</button><button class="next">›</button><div class="dots"></div></section><section id="cats"><h2>✦　تسوّق حسب القسم　✦</h2><div class="carousel"><button id="left">‹</button><div class="track"><?php foreach($cats as $i=>$c):?><button class="cat <?=$i===0?'active':''?>" data-id="<?=h($c['id'])?>"><span><?php if($c['image']):?><img src="<?=h($c['image'])?>"><?php else:?>✧<?php endif?></span><b><?=h($c['name'])?></b></button><?php endforeach?></div><button id="right">›</button></div></section><section id="products"><h2>✦　أحدث المنتجات　✦</h2><div class="grid"><?php foreach($products as $p):?><article><img src="<?=h($p['image_url'])?>" alt=""><h3><?=h($p['name'])?></h3><strong><?=number_format((float)$p['price'])?> ر.س</strong><button class="gold">أضف إلى السلة 🛒</button></article><?php endforeach?></div></section><footer>© <?=date('Y')?> الفخامة - جميع الحقوق محفوظة</footer><script src="assets/js/store.js"></script></body></html>